FILES = {'backend/services/ecmwf_wind_forcing.py': 'from __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom datetime import datetime, timedelta, timezone\nfrom pathlib import Path\nfrom typing import Iterable\n\nimport numpy as np\nimport xarray as xr\n\nfrom backend.services.ecmwf_weather_provider import (\n    CachedAsset,\n    EcmwfOpenDataWeatherProvider,\n    WeatherProviderError,\n    WeatherSourceUnavailable,\n    WeatherTimeUnavailable,\n)\nfrom backend.services.weather_math import longitude_for_dataset\n\n\n@dataclass\nclass EcmwfWindForcingCube:\n    dataset: xr.Dataset\n    forecast_reference_time: datetime\n    start_time: datetime\n    end_time: datetime\n    steps: tuple[int, ...]\n    sources: tuple[str, ...]\n    fallback_used: bool\n    retrieved_at: datetime\n    bbox: dict[str, float]\n\n    def provenance(self) -> dict:\n        return {\n            "provider": "ecmwf",\n            "model": "ifs",\n            "product": "open-data-0p25",\n            "forecast_reference_time": (\n                self.forecast_reference_time.isoformat()\n            ),\n            "start_time": self.start_time.isoformat(),\n            "end_time": self.end_time.isoformat(),\n            "steps": list(self.steps),\n            "sources": list(self.sources),\n            "fallback_used": self.fallback_used,\n            "retrieved_at": self.retrieved_at.isoformat(),\n            "bbox": dict(self.bbox),\n            "variables": ["u10", "v10"],\n            "opendrift_variables": ["x_wind", "y_wind"],\n            "temporal_interpolation": "OpenDrift reader interpolation",\n        }\n\n\ndef _utc(value: datetime) -> datetime:\n    if value.tzinfo is None:\n        return value.replace(tzinfo=timezone.utc)\n    return value.astimezone(timezone.utc)\n\n\ndef _numpy_datetime_to_utc(value) -> datetime:\n    raw = np.asarray(value).reshape(-1)[0]\n    value_ns = np.datetime64(raw, "ns").astype("int64")\n    return datetime.fromtimestamp(\n        value_ns / 1_000_000_000,\n        tz=timezone.utc,\n    )\n\n\ndef required_wind_steps(\n    *,\n    run: datetime,\n    start_time: datetime,\n    end_time: datetime,\n) -> tuple[int, ...]:\n    """\n    Return forecast steps bracketing the full simulation interval.\n\n    The first slice is at or before the simulation start and the final slice\n    is at or after the simulation end, allowing the OpenDrift reader to\n    interpolate wind in time between native IFS forecast steps.\n    """\n    run_utc = _utc(run)\n    start = _utc(start_time)\n    end = _utc(end_time)\n\n    if end <= start:\n        raise ValueError("end_time must be after start_time")\n\n    schedule = EcmwfOpenDataWeatherProvider._steps_for_run(run_utc)\n    start_hours = (start - run_utc).total_seconds() / 3600.0\n    end_hours = (end - run_utc).total_seconds() / 3600.0\n\n    if start_hours < 0.0:\n        raise WeatherTimeUnavailable(\n            "simulation start precedes the selected ECMWF forecast run"\n        )\n\n    before = [\n        step\n        for step in schedule\n        if step <= start_hours + 1e-9\n    ]\n    after = [\n        step\n        for step in schedule\n        if step >= end_hours - 1e-9\n    ]\n\n    if not before or not after:\n        raise WeatherTimeUnavailable(\n            "simulation interval is outside the available "\n            "ECMWF forecast horizon"\n        )\n\n    first = before[-1]\n    last = after[0]\n\n    return tuple(\n        step\n        for step in schedule\n        if first <= step <= last\n    )\n\n\nclass EcmwfWindForcingBuilder:\n    """\n    Build a cropped time × latitude × longitude IFS 10 m wind cube.\n\n    The builder reuses WEATHER-1.1 mirror failover and deterministic GRIB\n    cache. It does not modify currents or run OpenDrift itself.\n    """\n\n    def __init__(\n        self,\n        *,\n        provider: EcmwfOpenDataWeatherProvider | None = None,\n    ):\n        self.provider = (\n            provider\n            if provider is not None\n            else EcmwfOpenDataWeatherProvider()\n        )\n\n    def _latest_run(self) -> tuple[datetime, str]:\n        errors: list[str] = []\n\n        for source in self.provider.sources:\n            try:\n                client = self.provider._client(source)\n                run = client.latest(\n                    type="fc",\n                    step=3,\n                    param="10u",\n                )\n                return _utc(run), source\n            except Exception as exc:\n                errors.append(\n                    f"{source}: {type(exc).__name__}: {exc}"\n                )\n\n        raise WeatherSourceUnavailable(\n            "unable to resolve latest ECMWF run: "\n            + " | ".join(errors)\n        )\n\n    def _source_order(\n        self,\n        preferred_source: str,\n    ) -> tuple[str, ...]:\n        return (\n            preferred_source,\n            *(\n                source\n                for source in self.provider.sources\n                if source != preferred_source\n            ),\n        )\n\n    def _retrieve_wind_asset(\n        self,\n        *,\n        run: datetime,\n        step: int,\n        preferred_source: str,\n    ) -> CachedAsset:\n        errors: list[str] = []\n\n        for source in self._source_order(preferred_source):\n            try:\n                client = self.provider._client(source)\n                return self.provider._retrieve_asset(\n                    client=client,\n                    source=source,\n                    run=run,\n                    step=step,\n                    params=["10u", "10v"],\n                    kind="wind",\n                )\n            except Exception as exc:\n                errors.append(\n                    f"{source}: {type(exc).__name__}: {exc}"\n                )\n\n        raise WeatherSourceUnavailable(\n            f"all ECMWF mirrors failed for wind step {step}: "\n            + " | ".join(errors)\n        )\n\n    @staticmethod\n    def _wind_dataset(datasets: list[xr.Dataset]) -> xr.Dataset:\n        for dataset in datasets:\n            if (\n                "u10" in dataset.data_vars\n                and "v10" in dataset.data_vars\n            ):\n                return dataset\n        raise WeatherProviderError(\n            "ECMWF wind GRIB does not contain both u10 and v10"\n        )\n\n    @staticmethod\n    def _crop_longitude(\n        dataset: xr.Dataset,\n        *,\n        west: float,\n        east: float,\n    ) -> xr.Dataset:\n        uses_360 = (\n            float(dataset["longitude"].max()) > 180.0\n        )\n        west_ds = longitude_for_dataset(\n            west,\n            dataset_uses_360=uses_360,\n        )\n        east_ds = longitude_for_dataset(\n            east,\n            dataset_uses_360=uses_360,\n        )\n\n        longitude = dataset["longitude"]\n        lon_min = float(longitude.min())\n        lon_max = float(longitude.max())\n\n        if west_ds <= east_ds:\n            return dataset.sel(\n                longitude=slice(west_ds, east_ds)\n            )\n\n        left = dataset.sel(\n            longitude=slice(west_ds, lon_max)\n        )\n        right = dataset.sel(\n            longitude=slice(lon_min, east_ds)\n        )\n        return xr.concat(\n            [left, right],\n            dim="longitude",\n        )\n\n    @classmethod\n    def _normalize_slice(\n        cls,\n        dataset: xr.Dataset,\n        *,\n        bbox: dict[str, float],\n    ) -> tuple[xr.Dataset, datetime]:\n        if "valid_time" not in dataset.coords:\n            raise WeatherProviderError(\n                "ECMWF wind dataset has no valid_time coordinate"\n            )\n\n        valid_time = _numpy_datetime_to_utc(\n            dataset["valid_time"].values\n        )\n\n        wind = dataset[["u10", "v10"]]\n\n        drop_coords = [\n            name\n            for name in (\n                "time",\n                "step",\n                "heightAboveGround",\n                "valid_time",\n            )\n            if name in wind.coords\n        ]\n        wind = wind.drop_vars(\n            drop_coords,\n            errors="ignore",\n        )\n\n        if (\n            "latitude" not in wind.coords\n            or "longitude" not in wind.coords\n        ):\n            raise WeatherProviderError(\n                "ECMWF wind dataset requires latitude/longitude coordinates"\n            )\n\n        wind = wind.sortby("latitude").sortby("longitude")\n\n        wind = wind.sel(\n            latitude=slice(\n                float(bbox["south"]),\n                float(bbox["north"]),\n            ),\n        )\n        wind = cls._crop_longitude(\n            wind,\n            west=float(bbox["west"]),\n            east=float(bbox["east"]),\n        )\n\n        if (\n            wind.sizes.get("latitude", 0) == 0\n            or wind.sizes.get("longitude", 0) == 0\n        ):\n            raise WeatherProviderError(\n                "requested forcing bbox does not intersect ECMWF grid"\n            )\n\n        # OpenDrift 1.14.x generic reader requires a true 1-D time axis.\n        wind = wind.expand_dims(\n            time=[valid_time.replace(tzinfo=None)]\n        )\n\n        return wind, valid_time\n\n    def build(\n        self,\n        *,\n        start_time: datetime,\n        hours: int,\n        bbox: dict[str, float],\n    ) -> EcmwfWindForcingCube:\n        if hours <= 0:\n            raise ValueError("hours must be positive")\n\n        start = _utc(start_time)\n        end = start + timedelta(hours=int(hours))\n\n        run, preferred_source = self._latest_run()\n        steps = required_wind_steps(\n            run=run,\n            start_time=start,\n            end_time=end,\n        )\n\n        slices: list[xr.Dataset] = []\n        sources: set[str] = set()\n        retrieved_times: list[datetime] = []\n        actual_times: list[datetime] = []\n\n        for step in steps:\n            asset = self._retrieve_wind_asset(\n                run=run,\n                step=step,\n                preferred_source=preferred_source,\n            )\n            datasets = self.provider._dataset_loader(\n                asset.path\n            )\n            dataset = self._wind_dataset(datasets)\n            normalized, valid_time = self._normalize_slice(\n                dataset,\n                bbox=bbox,\n            )\n\n            slices.append(normalized)\n            sources.add(asset.source)\n            retrieved_times.append(asset.retrieved_at)\n            actual_times.append(valid_time)\n\n        cube = xr.concat(\n            slices,\n            dim="time",\n            data_vars="minimal",\n            coords="minimal",\n            compat="override",\n            join="exact",\n        ).sortby("time")\n\n        # Make the cube explicit and compact before handing it to OpenDrift.\n        cube = cube[["u10", "v10"]]\n        cube.attrs.update(\n            {\n                "provider": "ecmwf",\n                "model": self.provider.model,\n                "product": f"open-data-{self.provider.resolution}",\n                "forecast_reference_time": run.isoformat(),\n            }\n        )\n\n        source_tuple = tuple(sorted(sources))\n        fallback_used = any(\n            source != self.provider.sources[0]\n            for source in source_tuple\n        )\n\n        return EcmwfWindForcingCube(\n            dataset=cube,\n            forecast_reference_time=run,\n            start_time=start,\n            end_time=end,\n            steps=steps,\n            sources=source_tuple,\n            fallback_used=fallback_used,\n            retrieved_at=max(retrieved_times),\n            bbox={\n                key: float(value)\n                for key, value in bbox.items()\n            },\n        )\n\n\ndef build_opendrift_wind_reader(\n    forcing: EcmwfWindForcingCube,\n):\n    try:\n        from opendrift.readers import (\n            reader_netCDF_CF_generic,\n        )\n    except ImportError as exc:\n        raise WeatherProviderError(\n            "OpenDrift is not installed"\n        ) from exc\n\n    return reader_netCDF_CF_generic.Reader(\n        forcing.dataset,\n        name="ECMWF IFS 10 m wind",\n        standard_name_mapping={\n            "u10": "x_wind",\n            "v10": "y_wind",\n        },\n    )\n', 'tests/test_ecmwf_wind_forcing.py': 'from datetime import datetime, timezone\nfrom pathlib import Path\nfrom types import SimpleNamespace\n\nimport numpy as np\nimport pytest\nimport xarray as xr\n\nfrom backend.services.ecmwf_weather_provider import (\n    EcmwfOpenDataWeatherProvider,\n    WeatherTimeUnavailable,\n)\nfrom backend.services.ecmwf_wind_forcing import (\n    EcmwfWindForcingBuilder,\n    required_wind_steps,\n)\n\n\nRUN = datetime(2026, 9, 19, 0, tzinfo=timezone.utc)\n\n\ndef test_required_steps_bracket_simulation_window():\n    steps = required_wind_steps(\n        run=RUN,\n        start_time=datetime(\n            2026, 9, 19, 7, tzinfo=timezone.utc\n        ),\n        end_time=datetime(\n            2026, 9, 19, 19, tzinfo=timezone.utc\n        ),\n    )\n\n    assert steps == (6, 9, 12, 15, 18, 21)\n\n\ndef test_required_steps_exact_boundaries():\n    steps = required_wind_steps(\n        run=RUN,\n        start_time=datetime(\n            2026, 9, 19, 9, tzinfo=timezone.utc\n        ),\n        end_time=datetime(\n            2026, 9, 19, 18, tzinfo=timezone.utc\n        ),\n    )\n\n    assert steps == (9, 12, 15, 18)\n\n\ndef test_required_steps_reject_start_before_run():\n    with pytest.raises(WeatherTimeUnavailable):\n        required_wind_steps(\n            run=RUN,\n            start_time=datetime(\n                2026, 9, 18, 23, tzinfo=timezone.utc\n            ),\n            end_time=datetime(\n                2026, 9, 19, 6, tzinfo=timezone.utc\n            ),\n        )\n\n\nclass FakeClient:\n    def __init__(self, source, log, fail=False):\n        self.source = source\n        self.log = log\n        self.fail = fail\n\n    def latest(self, **kwargs):\n        if self.fail:\n            raise RuntimeError("mirror unavailable")\n        return RUN\n\n    def retrieve(self, **kwargs):\n        if self.fail:\n            raise RuntimeError("mirror unavailable")\n\n        path = Path(kwargs["target"])\n        path.write_bytes(b"fake-grib")\n        self.log.append(\n            (self.source, int(kwargs["step"]))\n        )\n        return SimpleNamespace(\n            datetime=RUN.replace(tzinfo=None)\n        )\n\n\ndef dataset_loader(path: Path):\n    step = int(\n        path.stem.split("step")[-1]\n    )\n    valid = np.datetime64(\n        RUN.replace(tzinfo=None)\n    ) + np.timedelta64(step, "h")\n\n    latitudes = np.array(\n        [46.0, 45.0, 44.0, 43.0],\n    )\n    longitudes = np.array(\n        [36.0, 37.0, 38.0, 39.0],\n    )\n\n    return [\n        xr.Dataset(\n            {\n                "u10": (\n                    ("latitude", "longitude"),\n                    np.full((4, 4), float(step)),\n                ),\n                "v10": (\n                    ("latitude", "longitude"),\n                    np.full((4, 4), -float(step)),\n                ),\n            },\n            coords={\n                "time": np.datetime64(\n                    RUN.replace(tzinfo=None)\n                ),\n                "step": np.timedelta64(step, "h"),\n                "heightAboveGround": 10.0,\n                "valid_time": valid,\n                "latitude": latitudes,\n                "longitude": longitudes,\n            },\n        )\n    ]\n\n\ndef make_builder(tmp_path, *, fail_google=False):\n    log = []\n\n    def factory(source):\n        return FakeClient(\n            source,\n            log,\n            fail=(\n                source == "google"\n                and fail_google\n            ),\n        )\n\n    provider = EcmwfOpenDataWeatherProvider(\n        cache_dir=tmp_path,\n        sources=("google", "azure"),\n        client_factory=factory,\n        dataset_loader=dataset_loader,\n        now_fn=lambda: datetime(\n            2026, 9, 19, 7, tzinfo=timezone.utc\n        ),\n    )\n\n    return EcmwfWindForcingBuilder(\n        provider=provider,\n    ), log\n\n\ndef test_builder_creates_cropped_time_cube(tmp_path):\n    builder, log = make_builder(tmp_path)\n\n    forcing = builder.build(\n        start_time=datetime(\n            2026, 9, 19, 7, tzinfo=timezone.utc\n        ),\n        hours=12,\n        bbox={\n            "west": 36.5,\n            "east": 38.5,\n            "south": 43.5,\n            "north": 45.5,\n        },\n    )\n\n    assert forcing.steps == (6, 9, 12, 15, 18, 21)\n    assert forcing.dataset.sizes["time"] == 6\n    assert forcing.dataset.sizes["latitude"] == 2\n    assert forcing.dataset.sizes["longitude"] == 2\n    assert list(forcing.dataset.data_vars) == [\n        "u10",\n        "v10",\n    ]\n    assert forcing.sources == ("google",)\n    assert forcing.fallback_used is False\n    assert log == [\n        ("google", 6),\n        ("google", 9),\n        ("google", 12),\n        ("google", 15),\n        ("google", 18),\n        ("google", 21),\n    ]\n\n\ndef test_builder_time_axis_is_monotonic(tmp_path):\n    builder, _ = make_builder(tmp_path)\n\n    forcing = builder.build(\n        start_time=datetime(\n            2026, 9, 19, 9, tzinfo=timezone.utc\n        ),\n        hours=9,\n        bbox={\n            "west": 36.0,\n            "east": 39.0,\n            "south": 43.0,\n            "north": 46.0,\n        },\n    )\n\n    values = forcing.dataset["time"].values\n    assert all(\n        values[index] < values[index + 1]\n        for index in range(len(values) - 1)\n    )\n\n\ndef test_builder_records_mirror_fallback(tmp_path):\n    builder, _ = make_builder(\n        tmp_path,\n        fail_google=True,\n    )\n\n    forcing = builder.build(\n        start_time=datetime(\n            2026, 9, 19, 7, tzinfo=timezone.utc\n        ),\n        hours=3,\n        bbox={\n            "west": 36.0,\n            "east": 39.0,\n            "south": 43.0,\n            "north": 46.0,\n        },\n    )\n\n    assert forcing.sources == ("azure",)\n    assert forcing.fallback_used is True\n    assert forcing.provenance()["opendrift_variables"] == [\n        "x_wind",\n        "y_wind",\n    ]\n', 'tools/weather1_3a_wind_forcing_probe.py': 'from __future__ import annotations\n\nimport argparse\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nimport sys\n\nREPO_ROOT = Path(__file__).resolve().parents[1]\nif str(REPO_ROOT) not in sys.path:\n    sys.path.insert(0, str(REPO_ROOT))\n\nfrom backend.services.ecmwf_wind_forcing import (\n    EcmwfWindForcingBuilder,\n    build_opendrift_wind_reader,\n)\n\n\ndef main() -> int:\n    parser = argparse.ArgumentParser(\n        description="WEATHER-1.3A ECMWF wind forcing cube live probe"\n    )\n    parser.add_argument("--lon", type=float, default=37.8)\n    parser.add_argument("--lat", type=float, default=44.6)\n    parser.add_argument("--hours", type=int, default=12)\n    parser.add_argument("--margin", type=float, default=2.0)\n    args = parser.parse_args()\n\n    start = datetime.now(timezone.utc).replace(\n        minute=0,\n        second=0,\n        microsecond=0,\n    )\n\n    bbox = {\n        "west": args.lon - args.margin,\n        "east": args.lon + args.margin,\n        "south": args.lat - args.margin,\n        "north": args.lat + args.margin,\n    }\n\n    builder = EcmwfWindForcingBuilder()\n    forcing = builder.build(\n        start_time=start,\n        hours=args.hours,\n        bbox=bbox,\n    )\n    reader = build_opendrift_wind_reader(\n        forcing\n    )\n\n    print("run:", forcing.forecast_reference_time.isoformat())\n    print("simulation start:", forcing.start_time.isoformat())\n    print("simulation end:", forcing.end_time.isoformat())\n    print("steps:", forcing.steps)\n    print("sources:", forcing.sources)\n    print("fallback_used:", forcing.fallback_used)\n    print("cube sizes:", dict(forcing.dataset.sizes))\n    print("cube variables:", list(forcing.dataset.data_vars))\n    print("reader variables:", reader.variables)\n    print("reader start_time:", reader.start_time)\n    print("reader end_time:", reader.end_time)\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'}


def backup(path: Path) -> Path:
    BACKUP_DIR.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    target = (
        BACKUP_DIR
        / f"{path.name}.before_weather1_3a_{stamp}"
    )
    shutil.copy2(path, target)
    return target


def main() -> int:
    prerequisites = [
        REPO_ROOT / "backend/services/ecmwf_weather_provider.py",
        REPO_ROOT / "backend/services/weather_math.py",
    ]

    for path in prerequisites:
        if not path.exists():
            print(
                f"ERROR: WEATHER prerequisite missing: {path}"
            )
            return 2

    backups = []

    for relative, content in FILES.items():
        path = REPO_ROOT / relative
        path.parent.mkdir(parents=True, exist_ok=True)

        if path.exists():
            existing = path.read_text(encoding="utf-8")
            if existing == content:
                continue
            backups.append(backup(path))

        path.write_text(content, encoding="utf-8")

    print("WEATHER-1.3A ECMWF Wind Forcing Cube v0.1 installed.")
    print("Created/updated:")
    for relative in FILES:
        print(f"  {relative}")
    print("No OceanDrift, FastAPI, or frontend files were modified.")

    if backups:
        print("Backups:")
        for item in backups:
            print(f"  {item.relative_to(REPO_ROOT)}")

    return 0


if __name__ == "__main__":
    sys.exit(main())
